    <script>
      document.addEventListener('DOMContentLoaded', function(){
        var form = document.getElementById('pkg-form-perfmkt_city_mumbai');
        if (!form) return;
        var tsEl = form.querySelector('input[name="form_ts"]');
        var nonceEl = form.querySelector('input[name="js_nonce"]');
        if (tsEl) tsEl.value = Math.floor(Date.now() / 1000);

        document.querySelectorAll('a.btn-sel').forEach(function(btn){
          btn.addEventListener('click', function(){
            var pkgName = btn.getAttribute('data-package');
            var sel = document.getElementById('pm_package');
            if (sel && pkgName) {
              for (var i = 0; i < sel.options.length; i++) {
                if (sel.options[i].value === pkgName) { sel.selectedIndex = i; break; }
              }
            }
          });
        });

        form.addEventListener('submit', function(e){
          e.preventDefault();
          var successBox = document.getElementById('pm-success-perfmkt_city_mumbai');
          var errorBox = document.getElementById('pm-error-perfmkt_city_mumbai');
          successBox.style.display = 'none';
          errorBox.style.display = 'none';
          var salt = 'itdgl-form-2026';
          var doFetch = function(){
            var fd = new FormData(form);
            fetch('/leadCaptureMail.php', {method:'POST', body: fd, credentials:'same-origin'})
              .then(function(r){ return r.json(); })
              .then(function(data){
                if (data && data.status === 'success') {
                  form.style.display = 'none';
                  successBox.style.display = 'block';
                  if (window.gtag) gtag('event','performance_marketing_package_enquiry', {package: fd.get('package') || 'not_selected', source: fd.get('source')});
                } else {
                  errorBox.style.display = 'block';
                }
              })
              .catch(function(){ errorBox.style.display = 'block'; });
          };
          if (tsEl && nonceEl && window.crypto && window.crypto.subtle) {
            var msg = new TextEncoder().encode(tsEl.value + '|' + salt);
            crypto.subtle.digest('SHA-256', msg).then(function(buf){
              var arr = Array.from(new Uint8Array(buf));
              nonceEl.value = arr.map(function(b){ return b.toString(16).padStart(2, '0'); }).join('');
              doFetch();
            }).catch(function(){ doFetch(); });
          } else {
            doFetch();
          }
        });
      });
    </script>

